OPENQASM 2.0;
include "qelib1.inc";
// 5-qubit Quantum Fourier Transform (structured, many small rotations)
// written out: H and controlled phases on each qubit, then swaps
qreg q[5];
h q[4];
cp(pi/2) q[3],q[4];
cp(pi/4) q[2],q[4];
cp(pi/8) q[1],q[4];
cp(pi/16) q[0],q[4];
h q[3];
cp(pi/2) q[2],q[3];
cp(pi/4) q[1],q[3];
cp(pi/8) q[0],q[3];
h q[2];
cp(pi/2) q[1],q[2];
cp(pi/4) q[0],q[2];
h q[1];
cp(pi/2) q[0],q[1];
h q[0];
swap q[0],q[4];
swap q[1],q[3];

OPENQASM 2.0;
include "qelib1.inc";
// Toffoli gate: flips q[2] when q[0] and q[1] are both 1
qreg q[3];
ccx q[0],q[1],q[2];

OPENQASM 2.0;
include "qelib1.inc";
// Cuccaro ripple-carry adder, 2+2 bits
// q[0] carry in; a = q[1], q[3]; b = q[2], q[4]; q[5] carry out
qreg q[6];
// MAJ(carry in, b0, a0)
cx q[1],q[2];
cx q[1],q[0];
ccx q[0],q[2],q[1];
// MAJ(a0, b1, a1)
cx q[3],q[4];
cx q[3],q[1];
ccx q[1],q[4],q[3];
// copy the carry out
cx q[3],q[5];
// UMA(a0, b1, a1)
ccx q[1],q[4],q[3];
cx q[3],q[1];
cx q[1],q[4];
// UMA(carry in, b0, a0)
ccx q[0],q[2],q[1];
cx q[1],q[0];
cx q[0],q[2];

OPENQASM 2.0;
include "qelib1.inc";
// 3-qubit Grover iteration: oracle marking |101>, then the diffuser
qreg q[3];
h q;
// oracle
x q[1];
h q[2];
ccx q[0],q[1],q[2];
h q[2];
x q[1];
// diffuser
h q;
x q;
h q[2];
ccx q[0],q[1],q[2];
h q[2];
x q;
h q;
